// Source transaction stages, not contact-pixel proof.
struct BridgeTransactionWitness {
    std::size_t active_case_index;
    std::size_t entry_event;
    std::size_t branch_event;
    std::size_t effects_event;
    std::size_t shot_clear_event;
    std::size_t score_before_event;
    std::size_t score_after_event;
    std::size_t lower_event;
    std::uint8_t contact_slot;
    std::uint8_t record_index;
    std::uint8_t contact_mask;
    bool primary;
    bool joint;
    bool player_fatal;
    std::uint8_t animation_role;
    std::uint16_t bridge_before;
    std::uint16_t bridge_after;
    std::uint8_t score_kind;
    std::uint32_t score_before;
    std::uint32_t score_after;
};

